class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        res, k = [], 0
        for r, row in enumerate(grid):
            for v in (row if r % 2 == 0 else row[::-1]):
                if k % 2 == 0:
                    res.append(v)
                k += 1
        return res

